use vstd::prelude::*;

verus! {

/// Spec-level bitwise xor on bytes, lifted to sequences.
spec fn seq_xor(a: Seq<u8>, b: Seq<u8>) -> Seq<u8>
    recommends
        a.len() == b.len(),
{
    Seq::new(a.len(), |i: int| a[i] ^ b[i])
}

fn bitwise_xor(a: Vec<u8>, b: Vec<u8>) -> (out: Vec<u8>)
    requires
        a@.len() == b@.len(),
        a@.len() > 0,
    ensures
        out@ == seq_xor(a@, b@),
        out@.len() == a@.len(),
{
    debug_assert_eq!(a.len(), b.len());
    debug_assert!(!a.is_empty());

    a.into_iter()
        .zip(b.into_iter())
        .map(|(x, y)| x ^ y)
        .collect()
}

} // verus!

